return items.map(item => {

  const updatedData = item.json.data.map(d => {

    if (d.success === true) {
      return {
        ...d,
        error: null,
        detailed_error: null
      };
    }

    let err = d.error;
    if (typeof err === "object") {
      err = JSON.stringify(err);
    }

    err = err || "";
    let detailed = err;
    detailed = detailed.replace(/<[^>]*>/g, " ");
    detailed = detailed.replace(/\n/g, " ");
    detailed = detailed.replace(/\s+/g, " ").trim();
    detailed = detailed.substring(0, 300);

    let friendly = "Something went wrong";
    const lower = detailed.toLowerCase();

    if (lower.includes("invalid") && lower.includes("token")) {
      friendly = "Authentication failed. Please reconnect your account.";
    } 
    else if (lower.includes("expired") && lower.includes("token")) {
      friendly = "Session expired. Please reconnect your account.";
    }
    else if (lower.includes("not available")) {
      friendly = "Token is not available or has been expired.";
    }
    else if (lower.includes("duplicate")) {
      friendly = "Duplicate post detected.";
    }
    else if (lower.includes("permission")) {
      friendly = "Permission denied. Check your account permissions.";
    }
    else if (lower.includes("rate limit")) {
      friendly = "Too many requests. Please try again later.";
    }

    return {
      ...d,
      error: friendly,
      detailed_error: detailed
    };
  });

  return {
    json: {
      ...item.json,
      data: updatedData
    }
  };
});

const input = $input.first().json;

let contentObj = input.content;

if (typeof contentObj === "string") {
  try {
    contentObj = JSON.parse(contentObj);
  } catch (e) {
    contentObj = { text: contentObj };
  }
}

const platforms = input.platforms || [];

const result = platforms.map(platform => {
  const content =
    (contentObj && contentObj[platform]) ||
    (contentObj && contentObj.text) ||
    "";

  const title =
    (input.title && input.title[platform]) ||
    (input.title && input.title.default) ||
    "";

  return {
    platform,
    content,
    title,
    image_url: input.image_url,
    tags: input.tags || [],
    user_id: input.user_id,
    scheduled_time: input.scheduled_time
  };
});

return result.map(r => ({ json: r }));

const dataRefineItems = $items("Data Refine");

const contentObj = {};

for (const item of dataRefineItems) {
  const platform = item.json.platform;
  const content = item.json.content;

  if (platform) {
    contentObj[platform] = content;
  }
}

const results = $json.results || [];

return [{
  user_id: $json.user_id,
  _id: $json._id,

  image_url: $json.image_url,

  content: contentObj, 
  results: results,       

  platform_posts: {
    linkedin: results.find(r => r.platform === 'linkedin')?.post_id || null,
    instagram: results.find(r => r.platform === 'instagram')?.post_id || null,
    reddit: results.find(r => r.platform === 'reddit')?.post_id || null,
    facebook: results.find(r => r.platform === 'facebook')?.post_id || null,
    twitter: results.find(r => r.platform === 'twitter')?.post_id || null
  },

  status: "active",
  version: 1,

  tracking: {
    enabled: true,
    interval_hours: 48,
    next_run_at: new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString(),
    expires_at: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString()
  },
  analytics: {
    history: [],
    last_checked: null
  },
  ai_suggestions: {
    status: "pending", 
    suggestion: null,
    user_action: null
  },
  created_at: new Date().toISOString(),
  updated_at: new Date().toISOString()
}];
